import type { Config, Stack } from "./config/schema";

const header =
	"# Generated by `cagr sync`. Edit cagr.toml and run `cagr sync` instead.";

/** A GitHub Actions expression. */
const expr = (inner: string) => `$${"{{"} ${inner} }}`;

function stackDir(stack: Stack) {
	const first = stack.paths[0] ?? "**";
	const dir = first.replace(/\/?\*\*.*$/, "").replace(/\/[^/]*\*.*$/, "");
	return dir === "" || dir.includes("*") ? "." : dir;
}

/** Steps that install each stack's tools and dependencies, once per manager and folder. */
function setupSteps(config: Config): string[] {
	const steps: string[] = [];
	const seen = new Set<string>();
	const once = (key: string, lines: string[]) => {
		if (seen.has(key)) return;
		seen.add(key);
		steps.push(...lines);
	};
	for (const stack of config.stack) {
		if (stack.language === "go")
			once("setup-go", [
				"      - uses: actions/setup-go@v5",
				"        with:",
				"          go-version: stable",
			]);
		if (stack.language === "rust")
			once("setup-rust", [
				"      - uses: dtolnay/rust-toolchain@stable",
				"        with:",
				"          components: rustfmt, clippy",
			]);
		const dir = stackDir(stack);
		const where = dir === "." ? [] : [`        working-directory: ${dir}`];
		switch (stack.package_manager) {
			case "bun":
				once("setup-bun", ["      - uses: oven-sh/setup-bun@v2"]);
				once(`bun:${dir}`, [
					"      - run: bun install --frozen-lockfile",
					...where,
				]);
				break;
			case "pnpm":
				once("setup-pnpm", [
					"      - uses: pnpm/action-setup@v4",
					"      - uses: actions/setup-node@v4",
					"        with:",
					"          node-version: lts/*",
				]);
				once(`pnpm:${dir}`, [
					"      - run: pnpm install --frozen-lockfile",
					...where,
				]);
				break;
			case "npm":
			case "yarn":
				once("setup-node", [
					"      - uses: actions/setup-node@v4",
					"        with:",
					"          node-version: lts/*",
				]);
				once(`${stack.package_manager}:${dir}`, [
					`      - run: ${stack.package_manager === "npm" ? "npm ci" : "yarn install --frozen-lockfile"}`,
					...where,
				]);
				break;
			case "uv":
				once("setup-uv", ["      - uses: astral-sh/setup-uv@v6"]);
				once(`uv:${dir}`, ["      - run: uv sync", ...where]);
				break;
			case "poetry":
			case "pip":
				once("setup-python", [
					"      - uses: actions/setup-python@v5",
					"        with:",
					"          python-version: '3.x'",
				]);
				once(`${stack.package_manager}:${dir}`, [
					`      - run: ${stack.package_manager === "poetry" ? "pipx install poetry && poetry install" : "pip install -r requirements.txt"}`,
					...where,
				]);
				break;
		}
	}
	return steps;
}

function installSteps(config: Config) {
	return [
		"      - name: Install cagr",
		"        run: |",
		`          ${config.ci.install}`,
		'          echo "$HOME/.local/bin" >> "$GITHUB_PATH"',
	];
}

const checkout = [
	"      - uses: actions/checkout@v4",
	"        with:",
	"          fetch-depth: 0",
	`          ref: ${expr("github.event.pull_request.head.sha || github.sha")}`,
];
const installClaude = [
	"      - uses: actions/setup-node@v4",
	"        with:",
	"          node-version: lts/*",
	"      - run: npm install -g @anthropic-ai/claude-code",
];

const secretEnv = [
	`          ANTHROPIC_API_KEY: ${expr("secrets.ANTHROPIC_API_KEY")}`,
	`          GH_TOKEN: ${expr("github.token")}`,
];

export function workflowYaml(config: Config): string {
	const nightly = config.ci.nightly;
	const lines = [
		header,
		"name: cagr",
		"on:",
		"  pull_request:",
		"    types: [opened, synchronize, reopened, ready_for_review, edited]",
		"  merge_group:",
		...(nightly.length > 0 ? ["  schedule:", "    - cron: '0 3 * * *'"] : []),
		"permissions:",
		"  contents: read",
		"concurrency:",
		`  group: cagr-${expr("github.event.pull_request.number || github.ref")}`,
		"  cancel-in-progress: true",
		"jobs:",
		"  checks:",
		"    if: github.event_name != 'schedule'",
		"    runs-on: ubuntu-latest",
		"    steps:",
		...checkout,
		...setupSteps(config),
		...installSteps(config),
		"      - run: cagr ci",
	];
	if (config.ci.review)
		lines.push(
			"  review:",
			// The review job runs on every event, edited too: a job skipped by its `if` counts as a passing required check.
			"    if: github.event_name == 'pull_request' && !github.event.pull_request.draft",
			"    runs-on: ubuntu-latest",
			"    permissions:",
			"      contents: read",
			"      pull-requests: write",
			"    steps:",
			// Without a ref, checkout gives the merge commit, which is not in the pull request.
			...checkout,
			...installClaude,
			...installSteps(config),
			"      - run: cagr review --ci",
			"        env:",
			...secretEnv,
		);
	if (nightly.length > 0)
		lines.push(
			"  nightly:",
			"    if: github.event_name == 'schedule'",
			"    runs-on: ubuntu-latest",
			"    permissions:",
			"      contents: read",
			"      issues: write",
			"    steps:",
			...checkout,
			...installClaude,
			...installSteps(config),
			`      - run: cagr review --scan ${nightly.map((glob) => `'${glob.replace(/'/g, "'\\''")}'`).join(" ")} --issue`,
			"        env:",
			...secretEnv,
		);
	return `${lines.join("\n")}\n`;
}

export function pullRequestTemplate(config: Config): string {
	const hints: Record<string, string> = {
		testing: "What you ran and what it showed.",
		risk: "What could break, and who would notice.",
		"how to revert":
			"The steps to undo this, and anything a plain revert would not undo.",
	};
	return `<!-- Generated by \`cagr sync\`. Edit [review] pr_sections in cagr.toml instead. -->\n\n## Summary\n\n${config.review.pr_sections
		.map(
			(section) =>
				`## ${section}\n\n${hints[section.toLowerCase()] ? `<!-- ${hints[section.toLowerCase()]} -->\n` : ""}`,
		)
		.join("\n")}`;
}

/** CODEOWNERS from [risk] owners. GitHub uses the last match, so later entries win as they do there. */
export function codeowners(config: Config): string | null {
	const entries = config.risk.paths.filter((entry) => entry.owners.length > 0);
	if (entries.length === 0) return null;
	const pattern = (glob: string) =>
		glob.includes("/") && !glob.startsWith("/") && !glob.startsWith("**")
			? `/${glob}`
			: glob;
	return `${header}\n${entries.map((entry) => `${pattern(entry.glob)} ${entry.owners.join(" ")}`).join("\n")}\n`;
}
